use strict;
use warnings;
use File::Find;
use File::Basename;

my $REPO = "/bench/repo";

my @ENTITIES = qw(
    Attachment Memo MemoRelation InstanceSetting User UserSetting
    IdentityProvider Inbox Reaction MemoShare UserIdentity
);

my @ENUMS = qw(RowStatus Visibility Role InboxStatus MemoRelationType);

sub is_data_layer {
    my ($path) = @_;
    my $rel = $path;
    $rel =~ s/^\Q$REPO\E\/?//;
    return ($rel eq "store" || $rel =~ /^store\//);
}

sub get_pkg_dir {
    my ($path) = @_;
    my $rel = $path;
    $rel =~ s/^\Q$REPO\E\/?//;
    $rel =~ s/\/[^\/]+$//;
    return $rel;
}

sub get_alias {
    my ($content) = @_;
    if ($content =~ /(\w+)\s+"github\.com\/usememos\/memos\/store"/) {
        my $a = $1;
        return $a unless $a eq "import";
    }
    return "store";
}

sub count_entity {
    my ($entity) = @_;
    my %pkgs;

    find(sub {
        return unless -f && /\.go$/;
        my $filepath = $File::Find::name;
        return if is_data_layer($filepath);

        open my $fh, "<", $filepath or return;
        local $/;
        my $content = <$fh>;
        close $fh;

        my $alias = get_alias($content);
        my $pat = qr/\b\Q$alias\E\.\Q$entity\E\b|\*\Q$alias\E\.\Q$entity\E\b|\[\]\*\Q$alias\E\.\Q$entity\E\b|\[\]\Q$alias\E\.\Q$entity\E\b/;

        if ($content =~ /$pat/) {
            my $pkg = get_pkg_dir($filepath);
            $pkgs{$pkg} = 1;
        }
    }, $REPO);

    return \%pkgs;
}

print "=== ENTITY TYPES ===\n";
my @results;
for my $e (@ENTITIES) {
    my $pkgs = count_entity($e);
    my @plist = sort keys %$pkgs;
    push @results, [$e, scalar(@plist), \@plist];
}
@results = sort { $b->[1] <=> $a->[1] || $a->[0] cmp $b->[0] } @results;

for my $r (@results) {
    my ($e, $cnt, $plist) = @$r;
    print "\n$e: $cnt packages\n";
    print "  - $_\n" for @$plist;
}

print "\n=== ENUM TYPES ===\n";
for my $e (@ENUMS) {
    my $pkgs = count_entity($e);
    print "$e: ", scalar(keys %$pkgs), " packages\n";
}
'

